              {!period && <p className="message">ElegÃ­ el perÃ­odo del sorteo.</p>}
              {period && !periodGames.length && <p className="message">No hay un juego activo asignado a este turno; no se mezclarÃ¡n juegos de otros sorteos.</p>}
